n.exploreUrl:
@js:
sort = [];
burl = "http://api.longchunbajiao.com";
push = (title, url, type1, type2) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: type1,
        layout_flexBasisPercent: type2
    }
});

// 男频榜单
push("♂男生", null, 1, 1);
const ranks = [
    ["必读榜", 1],
    ["完本榜", 2],
    ["更新榜", 3],
    ["搜索榜", 4],
    ["潜力榜", 5],
    ["评论榜", 6]
];
ranks.map(([title, type]) => {
    const url = `${burl}/module/rank?type=${type}&channel=1&page={{page}}`;
    push(title, url, 1, 0.25);
});

// 女频榜单
push("♀女生", null, 1, 1);
ranks.map(([title, type]) => {
    const url = `${burl}/module/rank?type=${type}&channel=2&page={{page}}`;
    push(title, url, 1, 0.25);
});

JSON.stringify(sort);

